{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://research.local/schema/h_idea-1.0.json",
  "title": "H_idea",
  "type": "object",
  "required": [
    "hypothesis_id",
    "version",
    "created_at",
    "generator_id",
    "context_snapshot_id",
    "idea_text",
    "hypothesis_class",
    "rationale",
    "expected_relation",
    "counteridea",
    "uncertainty"
  ],
  "properties": {
    "hypothesis_id": {
      "type": "string"
    },
    "version": {
      "type": "integer",
      "minimum": 1
    },
    "parent_hypothesis_ids": {
      "type": "array",
      "items": { "type": "string" }
    },
    "created_at": {
      "type": "string",
      "format": "date-time"
    },
    "generator_id": {
      "type": "string"
    },
    "generator_version": {
      "type": "string"
    },
    "context_snapshot_id": {
      "type": "string"
    },
    "idea_text": {
      "type": "string",
      "minLength": 1
    },
    "hypothesis_class": {
      "enum": [
        "difference",
        "association",
        "change",
        "interaction",
        "boundary_condition",
        "mechanism",
        "other"
      ]
    },
    "observation_basis": {
      "type": "array",
      "items": { "type": "string" }
    },
    "knowledge_basis_refs": {
      "type": "array",
      "items": { "type": "string" }
    },
    "rationale": {
      "type": "string"
    },
    "expected_relation": {
      "type": "string"
    },
    "counteridea": {
      "type": "string"
    },
    "proposed_features": {
      "type": "array",
      "items": { "type": "string" }
    },
    "proposed_scope": {
      "type": ["string", "null"]
    },
    "proposed_horizon": {
      "type": ["string", "null"]
    },
    "mechanism_text": {
      "type": ["string", "null"]
    },
    "derived_testable_consequences": {
      "type": "array",
      "items": { "type": "string" }
    },
    "uncertainty": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    }
  },
  "additionalProperties": false
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://research.local/schema/h_exec-1.0.json",
  "title": "H_exec",
  "type": "object",
  "required": [
    "hypothesis_id",
    "source_idea_id",
    "schema_version",
    "hypothesis_class",
    "scope",
    "conditions",
    "outcome",
    "counter_event",
    "observation_horizon",
    "outcome_horizon",
    "feature_refs",
    "evaluation_policy_id"
  ],
  "properties": {
    "hypothesis_id": {
      "type": "string"
    },
    "source_idea_id": {
      "type": "string"
    },
    "schema_version": {
      "type": "string"
    },
    "hypothesis_class": {
      "enum": [
        "difference",
        "association",
        "change",
        "interaction",
        "boundary_condition"
      ]
    },
    "scope": {
      "type": "object",
      "required": ["instrument_set", "session_rules"],
      "properties": {
        "instrument_set": {
          "type": "array",
          "items": { "type": "string" }
        },
        "session_rules": {
          "type": "array",
          "items": { "type": "string" }
        },
        "regime_conditions": {
          "type": "array",
          "items": { "type": "string" }
        }
      }
    },
    "conditions": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["feature_ref", "operator", "value"],
        "properties": {
          "feature_ref": { "type": "string" },
          "operator": {
            "enum": [
              "gt",
              "gte",
              "lt",
              "lte",
              "eq",
              "neq",
              "between",
              "crosses_above",
              "crosses_below"
            ]
          },
          "value": {}
        }
      }
    },
    "outcome": {
      "type": "object",
      "required": ["type", "definition"],
      "properties": {
        "type": {
          "enum": ["binary", "continuous"]
        },
        "definition": {
          "type": "string"
        },
        "feature_ref": {
          "type": ["string", "null"]
        }
      }
    },
    "counter_event": {
      "type": "string"
    },
    "observation_horizon": {
      "type": "string"
    },
    "outcome_horizon": {
      "type": "string"
    },
    "exclusions": {
      "type": "array",
      "items": { "type": "string" }
    },
    "feature_refs": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["feature_id", "feature_version"],
        "properties": {
          "feature_id": { "type": "string" },
          "feature_version": { "type": "string" }
        }
      }
    },
    "baseline_definition": {
      "type": "string"
    },
    "evaluation_policy_id": {
      "type": "string"
    },
    "language_version": {
      "type": "string"
    }
  },
  "additionalProperties": false
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://research.local/schema/feature-1.0.json",
  "title": "FeatureDefinition",
  "type": "object",
  "required": [
    "feature_id",
    "version",
    "feature_type",
    "semantic_definition",
    "inputs",
    "availability_rule",
    "golden_cases"
  ],
  "properties": {
    "feature_id": {
      "type": "string"
    },
    "version": {
      "type": "string"
    },
    "feature_type": {
      "enum": ["composition", "primitive"]
    },
    "semantic_definition": {
      "type": "string"
    },
    "inputs": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name", "source"],
        "properties": {
          "name": { "type": "string" },
          "source": { "type": "string" }
        }
      }
    },
    "parameters": {
      "type": "object"
    },
    "lookback": {
      "type": ["string", "null"]
    },
    "availability_rule": {
      "type": "string"
    },
    "units": {
      "type": ["string", "null"]
    },
    "composition_expression": {
      "type": ["string", "null"]
    },
    "expected_invariants": {
      "type": "array",
      "items": { "type": "string" }
    },
    "edge_cases": {
      "type": "array",
      "items": { "type": "string" }
    },
    "golden_cases": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["input", "expected_output"],
        "properties": {
          "input": {},
          "expected_output": {},
          "explanation": {
            "type": "string"
          }
        }
      }
    },
    "author_agent_id": {
      "type": "string"
    }
  },
  "additionalProperties": false
}

